mount.import:
import { PrivacyRegistry } from './registry.js';
import { createMemoryConsentStore } from './consent.js';
import { createPrivacyRouter } from './privacy.js';
import { requireAuth } from './auth.js';

mount.use:
const registry = new PrivacyRegistry();
registry.register({ name: 'profil', collect: (uid) => db.prepare('SELECT * FROM users WHERE id = ?').get(uid), erase: (uid) => db.prepare('DELETE FROM users WHERE id = ?').run(uid).changes });
// Monter DERRIÈRE l'auth (req.user.id) :
app.use('/api/privacy', requireAuth(process.env.AUTH_SECRET!), createPrivacyRouter({ registry, consents: createMemoryConsentStore() }));
